
$(function () {
    "use strict";

    /* =========================
       Navbar Background
    ========================= */

    const $navbar = $(".navbar");

    if ($navbar.length) {
        function updateNavbarBackground() {
            $navbar.toggleClass(
                "is-scrolled",
                window.scrollY > 50
            );
        }

        $(window).on("scroll", updateNavbarBackground);
        updateNavbarBackground();
    }

    /* =========================
       Dynamic Copyright Year
    ========================= */

    const $copyrightYear = $("#copyright-year");

    if ($copyrightYear.length) {
        $copyrightYear.text(new Date().getFullYear());
    }

    /* =========================
       Section Scroll Reveal
    ========================= */

    const $sections = $("main > section");

    const reducedMotion = window.matchMedia(
        "(prefers-reduced-motion: reduce)"
    ).matches;

    if (!reducedMotion && "IntersectionObserver" in window) {

        // Add reveal classes to section content
        $sections.each(function () {
            const $content = $(this).children(
                ".container, .container-fluid, #cover-caption"
            );

            $content.addClass("reveal-content");
        });

        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    const $content = $(entry.target).children(
                        ".reveal-content"
                    );

                    $content.toggleClass(
                        "is-visible",
                        entry.isIntersecting
                    );
                });
            },
            {
                threshold: 0.05,
                rootMargin: "0px 0px -5% 0px"
            }
        );

        $sections.each(function () {
            observer.observe(this);
        });
    }
});
